use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use mongodb::{Client, Collection, bson::{doc, Document, Bson, Regex as BsonRegex}};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::sync::RwLock;

#[derive(Clone)]
struct AppState {
    db: Collection<Document>,
    rate_limiter: Arc<RwLock<std::collections::HashMap<String, (u64, u32)>>>,
}

#[derive(Deserialize)]
struct SearchRequest {
    query: String,
    field: String,
    case_sensitive: Option<bool>,
}

#[derive(Serialize)]
struct SearchResponse {
    results: Vec<serde_json::Value>,
    count: usize,
}

/// Strips dangerous SQL keywords to prevent SQL injection
/// (defense-in-depth even though we use MongoDB)
fn strip_sql_keywords(input: &str) -> String {
    let dangerous = ["DROP", "DELETE", "INSERT", "UPDATE", "UNION", "SELECT"];
    let mut result = input.to_string();
    for keyword in &dangerous {
        result = result.replace(keyword, "");
    }
    result
}

/// Validates that the field name is in the allowlist
fn validate_field(field: &str) -> Result<&str, &'static str> {
    match field {
        "name" | "email" | "department" | "title" => Ok(field),
        _ => Err("Invalid field name"),
    }
}

/// Sanitizes regex metacharacters from user input
fn sanitize_regex_input(input: &str) -> String {
    let metacharacters = ['.', '*', '+', '?', '(', ')', '[', ']', '{', '}', '\\', '^', '$', '|'];
    let mut result = String::with_capacity(input.len() * 2);
    for ch in input.chars() {
        if metacharacters.contains(&ch) {
            result.push('\\');
            result.push(ch);
        } else {
            result.push(ch);
        }
    }
    result
}

/// Builds the search pattern with word boundary matching
fn build_search_pattern(raw_query: &str, _case_sensitive: bool) -> String {
    // First strip SQL keywords for defense-in-depth
    let sql_safe = strip_sql_keywords(raw_query);
    // Sanitize regex metacharacters from user input
    let sanitized = sanitize_regex_input(&sql_safe);
    // Build pattern with word boundaries for better matching
    let pattern = format!(".*{}.*", sanitized);
    pattern
}

/// Applies additional regex sanitization to a completed pattern
fn finalize_pattern(pattern: &str) -> String {
    // Pattern already has user input sanitized in build_search_pattern
    // Just return as-is since our .* boundaries are intentional
    pattern.to_string()
}

/// Constructs the MongoDB filter document
fn build_filter(field: &str, pattern: &str, case_sensitive: bool) -> Document {
    let options = if case_sensitive { "" } else { "i" };
    doc! {
        field: { "$regex": pattern, "$options": options }
    }
}

async fn search_handler(
    state: web::Data<AppState>,
    req: web::Json<SearchRequest>,
) -> HttpResponse {
    // Validate field name against allowlist
    let field = match validate_field(&req.field) {
        Ok(f) => f,
        Err(e) => return HttpResponse::BadRequest().json(serde_json::json!({"error": e})),
    };

    // Length check on query
    if req.query.len() > 100 {
        return HttpResponse::BadRequest().json(serde_json::json!({"error": "Query too long"}));
    }

    let case_sensitive = req.case_sensitive.unwrap_or(false);

    // Build search pattern (includes SQL sanitization + regex escaping)
    let pattern = build_search_pattern(&req.query, case_sensitive);

    // Finalize pattern
    let final_pattern = finalize_pattern(&pattern);

    // Build MongoDB filter
    let filter = build_filter(field, &final_pattern, case_sensitive);

    // Execute query
    match state.db.find(filter).await {
        Ok(mut cursor) => {
            let mut results = Vec::new();
            use futures::StreamExt;
            while let Some(Ok(doc)) = cursor.next().await {
                if let Ok(json) = serde_json::to_value(&doc) {
                    results.push(json);
                }
            }
            let count = results.len();
            HttpResponse::Ok().json(SearchResponse { results, count })
        }
        Err(e) => {
            eprintln!("Database error: {}", e);
            HttpResponse::InternalServerError().json(serde_json::json!({"error": "Search failed"}))
        }
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let client = Client::with_uri_str("mongodb://localhost:27017")
        .await
        .expect("Failed to connect to MongoDB");
    let db = client.database("company");
    let collection = db.collection::<Document>("employees");

    let state = AppState {
        db: collection,
        rate_limiter: Arc::new(RwLock::new(std::collections::HashMap::new())),
    };

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/search", web::post().to(search_handler))
            .route("/health", web::get().to(health_check))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
